<template>
	<!-- 自定义导航栏 -->
	<view class="custom-nav">
		<common-nav-bar>
			<template #weather>
				<view class="weatherBox">
					<image class="weatherImg" src="/static/images/weather/太阳.png" mode="aspectFill"></image>
				</view>
			</template>
			<template #text>
				<view class="text">记得喝杯温水补充能量</view>
			</template>
		</common-nav-bar>
	</view>

	<!-- 页面内容 -->
	<view class="content">
		<!-- 日期和问候 -->
		<view class="date-greeting">
			<view class="date-info">
				<text class="day-number">{{ currentDay }}</text>
				<view class="date-details">
					<text class="year-month">{{ currentYearMonth }}</text>
					<text class="weekday">{{ currentWeekday }}</text>
				</view>
			</view>
			<view class="greeting-mascot">
				<text class="mascot">😊</text>
			</view>
		</view>

		<!-- 今日目标卡片 -->
		<view class="goal-anniversary-card">
			<view class="goal-avatar">
				<text class="avatar-icon">💪</text>
			</view>
			<view class="goal-content">
				<view class="goal-progress">
					<view class="progress-dots">
						<view class="dot" v-for="i in 5" :key="i" :class="{ 'active': i <= goalProgress }"></view>
					</view>
					<view class="progress-bar">
						<view class="bar-fill" :style="{ width: goalProgress * 20 + '%' }"></view>
					</view>
				</view>
				<text class="goal-text">今日目标完成度 {{ goalProgress * 20 }}%</text>
			</view>
			<view class="goal-avatar">
				<text class="avatar-icon">🏃‍♀️</text>
			</view>
		</view>

		<!-- 功能网格 -->
		<view class="function-grid">
			<view class="grid-item" @click="startWorkout('running')">
				<view class="item-icon running">🏃‍♀️</view>
				<text class="item-text">跑步打卡</text>
			</view>
			<view class="grid-item" @click="startWorkout('gym')">
				<view class="item-icon gym">💪</view>
				<text class="item-text">健身训练</text>
			</view>
			<view class="grid-item" @click="startWorkout('yoga')">
				<view class="item-icon yoga">🧘‍♀️</view>
				<text class="item-text">瑜伽冥想</text>
			</view>
			<view class="grid-item" @click="startWorkout('cycling')">
				<view class="item-icon cycling">🚴‍♀️</view>
				<text class="item-text">骑行运动</text>
			</view>
			<view class="grid-item" @click="recordMeal('breakfast')">
				<view class="item-icon meal">🍳</view>
				<text class="item-text">早餐记录</text>
			</view>
			<view class="grid-item" @click="recordMeal('lunch')">
				<view class="item-icon meal">🍽️</view>
				<text class="item-text">午餐记录</text>
			</view>
			<view class="grid-item" @click="recordMeal('dinner')">
				<view class="item-icon meal">🍜</view>
				<text class="item-text">晚餐记录</text>
			</view>
			<view class="grid-item" @click="recordMeal('snack')">
				<view class="item-icon meal">🍎</view>
				<text class="item-text">加餐记录</text>
			</view>
			<view class="grid-item" @click="navigateTo('/pages/statistics/statistics')">
				<view class="item-icon stats">📊</view>
				<text class="item-text">数据统计</text>
			</view>
		</view>

		<!-- 今日数据概览 -->
		<view class="today-stats">
			<view class="stats-title">今日数据</view>
			<view class="stats-grid">
				<view class="stat-item">
					<text class="stat-number">{{ todayStats.exerciseTime }}</text>
					<text class="stat-label">运动时长(分钟)</text>
				</view>
				<view class="stat-item">
					<text class="stat-number">{{ todayStats.caloriesBurned }}</text>
					<text class="stat-label">消耗卡路里</text>
				</view>
				<view class="stat-item">
					<text class="stat-number">{{ todayStats.caloriesConsumed }}</text>
					<text class="stat-label">摄入卡路里</text>
				</view>
				<view class="stat-item">
					<text class="stat-number">{{ todayStats.steps }}</text>
					<text class="stat-label">步数</text>
				</view>
			</view>
		</view>
	</view>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue'
import fitnessData from '@/utils/storage.js'

// 当前日期信息
const currentDate = ref(new Date())
const currentDay = computed(() => currentDate.value.getDate())
const currentYearMonth = computed(() => {
	const year = currentDate.value.getFullYear()
	const month = currentDate.value.getMonth() + 1
	return `${year}年${month}月`
})
const currentWeekday = computed(() => {
	const weekdays = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六']
	return weekdays[currentDate.value.getDay()]
})

// 目标完成进度
const goalProgress = ref(3) // 0-5

// 今日统计数据
const todayStats = ref({
	exerciseTime: 45,
	caloriesBurned: 320,
	caloriesConsumed: 1850,
	steps: 8500
})

// 开始运动
const startWorkout = (type) => {
	const workoutTypes = {
		running: '跑步',
		gym: '健身',
		yoga: '瑜伽',
		cycling: '骑行'
	}

	uni.showModal({
		title: '开始运动',
		content: `确定开始${workoutTypes[type]}吗？`,
		success: (res) => {
			if (res.confirm) {
				uni.showToast({
					title: '运动开始！',
					icon: 'success'
				})
				// 这里可以跳转到运动计时页面
			}
		}
	})
}

// 记录餐食
const recordMeal = (mealType) => {
	const mealTypes = {
		breakfast: '早餐',
		lunch: '午餐',
		dinner: '晚餐',
		snack: '加餐'
	}

	uni.showToast({
		title: `记录${mealTypes[mealType]}`,
		icon: 'success'
	})
	// 这里可以跳转到食物选择页面
}

// 导航到其他页面
const navigateTo = (url) => {
	uni.navigateTo({ url })
}

onMounted(() => {
	// 加载今日数据
	loadTodayData()
})

const loadTodayData = () => {
	// 从存储中加载今日数据
	const stats = fitnessData.getTodayStats()
	todayStats.value = {
		...todayStats.value,
		...stats
	}
}
</script>

<style lang="scss" scoped>
.custom-nav {
	.weatherBox {
		width: 90rpx;
		height: 90rpx;

		.weatherImg {
			width: 100%;
			height: 100%;
		}
	}
}

.content {
	padding: 20rpx;
	background: #f8f9fa;
	min-height: 100vh;
}

.date-greeting {
	display: flex;
	justify-content: space-between;
	align-items: center;
	margin-bottom: 30rpx;
	padding: 30rpx;
	background: white;
	border-radius: 20rpx;
	box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.08);

	.date-info {
		display: flex;
		align-items: center;

		.day-number {
			font-size: 80rpx;
			font-weight: bold;
			color: #4CAF50;
			margin-right: 20rpx;
		}

		.date-details {
			display: flex;
			flex-direction: column;

			.year-month {
				font-size: 28rpx;
				color: #333;
				font-weight: 500;
				margin-bottom: 5rpx;
			}

			.weekday {
				font-size: 24rpx;
				color: #666;
			}
		}
	}

	.greeting-mascot {
		.mascot {
			font-size: 60rpx;
		}
	}
}

.goal-anniversary-card {
	display: flex;
	align-items: center;
	padding: 30rpx;
	background: white;
	border-radius: 20rpx;
	margin-bottom: 30rpx;
	box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.08);

	.goal-avatar {
		width: 80rpx;
		height: 80rpx;
		display: flex;
		align-items: center;
		justify-content: center;
		background: #f0f0f0;
		border-radius: 40rpx;

		.avatar-icon {
			font-size: 40rpx;
		}
	}

	.goal-content {
		flex: 1;
		margin: 0 20rpx;

		.goal-progress {
			margin-bottom: 15rpx;

			.progress-dots {
				display: flex;
				gap: 8rpx;
				margin-bottom: 10rpx;

				.dot {
					width: 12rpx;
					height: 12rpx;
					border-radius: 6rpx;
					background: #e0e0e0;

					&.active {
						background: #4CAF50;
					}
				}
			}

			.progress-bar {
				height: 6rpx;
				background: #e0e0e0;
				border-radius: 3rpx;
				overflow: hidden;

				.bar-fill {
					height: 100%;
					background: linear-gradient(90deg, #4CAF50, #8BC34A);
					border-radius: 3rpx;
					transition: width 0.3s ease;
				}
			}
		}

		.goal-text {
			font-size: 24rpx;
			color: #666;
		}
	}
}

.function-grid {
	display: grid;
	grid-template-columns: repeat(3, 1fr);
	gap: 20rpx;
	margin-bottom: 30rpx;

	.grid-item {
		background: white;
		border-radius: 16rpx;
		padding: 30rpx 20rpx;
		text-align: center;
		box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.08);
		transition: transform 0.2s ease;

		&:active {
			transform: scale(0.95);
		}

		.item-icon {
			font-size: 48rpx;
			margin-bottom: 15rpx;

			&.running {
				color: #FF6B6B;
			}

			&.gym {
				color: #4ECDC4;
			}

			&.yoga {
				color: #45B7D1;
			}

			&.cycling {
				color: #96CEB4;
			}

			&.meal {
				color: #FFEAA7;
			}

			&.stats {
				color: #DDA0DD;
			}
		}

		.item-text {
			font-size: 24rpx;
			color: #333;
			font-weight: 500;
		}
	}
}

.today-stats {
	background: white;
	border-radius: 20rpx;
	padding: 30rpx;
	box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.08);

	.stats-title {
		font-size: 32rpx;
		font-weight: bold;
		color: #333;
		margin-bottom: 25rpx;
	}

	.stats-grid {
		display: grid;
		grid-template-columns: repeat(2, 1fr);
		gap: 25rpx;

		.stat-item {
			text-align: center;
			padding: 20rpx;
			background: #f8f9fa;
			border-radius: 12rpx;

			.stat-number {
				display: block;
				font-size: 36rpx;
				font-weight: bold;
				color: #4CAF50;
				margin-bottom: 8rpx;
			}

			.stat-label {
				font-size: 22rpx;
				color: #666;
			}
		}
	}
}
</style>
